UPDATE lab_learning_roadmap
SET status = #{targetStatus}, update_time = #{updateTime}
WHERE id = #{roadmapId} AND status = #{currentStatus}

UPDATE lab_learning_roadmap
title = #{title}, description = #{description}, difficulty = #{difficulty}, estimated_hours = #{estimatedHours}, cover_media_id = #{coverMediaId}, sort_order = #{sortOrder}, update_time = #{updateTime}
WHERE id = #{id} AND status != 'ARCHIVED'

UPDATE lab_learning_stage

    name = #{name},
    description = #{description},
    sort_order = #{sortOrder},
    update_time = #{updateTime}

WHERE id = #{id}
  AND EXISTS (
      SELECT 1 FROM lab_learning_roadmap r
      WHERE r.id = lab_learning_stage.roadmap_id AND r.status != 'ARCHIVED'
  )

UPDATE lab_learning_unit
title = #{title}, description = #{description}, sort_order = #{sortOrder}, update_time = #{updateTime}
WHERE id = #{id} AND EXISTS ( SELECT 1 FROM lab_learning_stage s INNER JOIN lab_learning_roadmap r ON r.id = s.roadmap_id WHERE s.id = lab_learning_unit.stage_id AND r.status != 'ARCHIVED' )

UPDATE lab_learning_record
SET status = 'IN_PROGRESS', completed_at = NULL, update_time = #{updateTime}
WHERE roadmap_id = #{roadmapId} AND status = 'COMPLETED'

UPDATE lab_learning_record
SET status = #{status}, completed_at = #{completedAt}, update_time = #{updateTime}
WHERE id = #{recordId}
